"""Bind to healthy014; enter only its namespaces, drop privileges, provision/test."""
import base64,hashlib,json,os,pathlib,pwd,stat,subprocess
P=pathlib.Path;BASE=P('/home/jwk/aenv-y-clean-20261111');UNIT='jwk-aenv-y-clean-20261111.service'
WORKER='';WORKER_SHA='d824709fe11bc3e4d9c28eadb3569f24020d773996e36349d66c24cb34869c39'
def digest(path):
    with path.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def main():
    assert os.getuid()==os.geteuid()==0;os.umask(0o077)
    user=pwd.getpwnam('jwk');assert user.pw_uid==user.pw_gid==1002
    previous=json.loads((BASE/'deployment014/result.json').read_text())
    assert previous['serviceStarted'] and previous['rust_health']==204 and previous['initial_fc_pool']['count']==300
    row=subprocess.run(['systemctl','show',UNIT,'-p','MainPID','-p','ActiveState'],capture_output=True,text=True,check=True)
    props=dict(line.split('=',1) for line in row.stdout.splitlines());pid=int(props['MainPID'])
    assert props['ActiveState']=='active' and pid==previous['serverPid']
    proc=P('/proc',str(pid));assert proc.stat().st_uid==1002
    inputs=json.loads((BASE/'runtime-prep005/result.json').read_text())
    assert digest(proc/'exe')==inputs['native_inputs']['server']['sha256']
    assert digest(BASE/'config/runtime005.toml')==inputs['service_configuration']['sha256']
    assert digest(BASE/'g4-benchmark_sandbox_lifecycle.py')=='7c26ea29fe8a117859365be18bd8893b1145b3e8c7bf9cdaaeb094a2d0e13263'
    context=previous['runtime_attestation']
    assert P('/proc/sys/kernel/random/boot_id').read_text().strip()==context['boot_id']
    assert (proc/'ns/net').stat().st_ino==context['netns'] and (proc/'ns/mnt').stat().st_ino==context['mntns']
    directory=BASE/'deployment015';assert not directory.exists();directory.mkdir(mode=0o700);os.chown(directory,1002,1002)
    raw=base64.b64decode(WORKER,validate=True);assert hashlib.sha256(raw).hexdigest()==WORKER_SHA;compile(raw,'wikidata015_worker.py','exec')
    worker=directory/'wikidata015_worker.py';worker.write_bytes(raw);os.chown(worker,1002,1002);worker.chmod(0o700)
    ca=json.loads((BASE/'config/egress-proxy.json').read_text())['ca']
    env={'PATH':'/usr/local/bin:/usr/local/sbin:/usr/bin:/usr/sbin:/bin:/sbin','HOME':user.pw_dir,'USER':'jwk','LOGNAME':'jwk','LANG':'C.UTF-8',
        'SSL_CERT_FILE':ca,'CURL_CA_BUNDLE':ca,'HTTP_PROXY':'http://127.0.0.1:18089','HTTPS_PROXY':'http://127.0.0.1:18089',
        'NO_PROXY':'localhost,127.0.0.1','no_proxy':'localhost,127.0.0.1','PYTHONNOUSERSITE':'1','PYTHONUNBUFFERED':'1'}
    command=['nsenter','--target',str(pid),'--net','--mount','--','setpriv','--reuid=1002','--regid=1002','--clear-groups',
        '--inh-caps=-all','--ambient-caps=-all','--bounding-set=-all','--no-new-privs','/usr/bin/python3','-I','-B',str(worker)]
    with (directory/'worker.log').open('xb') as log:
        code=subprocess.run(command,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=10300).returncode
    log=(directory/'worker.log').read_text(errors='replace')
    assert len(log.encode())<1900000,'Result log too large; preserve on Y'
    print(log,flush=True)
    assert code==0,'Native template/benchmark task failed; inspect persisted state; service is preserved'
if __name__=='__main__':main()
